#!/usr/bin/env node
/**
 * Derives the scene geometry and the favicon from ONE master: the brand
 * artwork at public/logos/zarnex-mark.svg.
 *
 * The mark used to exist twice — once as artwork, once as hand-typed
 * coordinates — which is the exact failure this codebase keeps getting bitten
 * by. Now there is one file, and `npm run check:mark` fails the build if the
 * generated copy drifts from it.
 *
 *   node scripts/build-mark.mjs          rewrite the generated files
 *   node scripts/build-mark.mjs --check  fail if they are out of date
 */
import { readFileSync, writeFileSync } from "node:fs";

const SVG = "public/logos/zarnex-mark.svg";
const TS = "src/components/scene/mark.ts";
const ICON = "src/app/icon.svg";
const BRONZE = "#b28e5e";

const svg = readFileSync(SVG, "utf8");
const d = svg.match(/ d="([^"]+)"/)?.[1];
if (!d) throw new Error(`no path data in ${SVG}`);

// The artwork is emitted as absolute M/L/Z subpaths only — keep it that way.
const unsupported = d.match(/[CcSsQqTtAaHhVvmlz]/);
if (unsupported) {
  throw new Error(
    `${SVG} uses "${unsupported[0]}" — this parser handles absolute M/L/Z only. ` +
      `Flatten curves before committing the artwork.`,
  );
}

const contours = d
  .split("M")
  .slice(1)
  .map((sub) =>
    sub
      .replace(/Z\s*$/, "")
      .split("L")
      .map((p) => p.trim().split(/[\s,]+/).map(Number)),
  );

const pts = contours.flat();
const xs = pts.map((p) => p[0]);
const ys = pts.map((p) => p[1]);
const [minx, maxx] = [Math.min(...xs), Math.max(...xs)];
const [miny, maxy] = [Math.min(...ys), Math.max(...ys)];
const cx = (minx + maxx) / 2;
const cy = (miny + maxy) / 2;
const s = Math.max(maxx - minx, maxy - miny) / 2;

const r4 = (n) => Math.round(n * 1e4) / 1e4;
const body = contours
  .map(
    (c) =>
      "  [" +
      c.map(([x, y]) => `[${r4((x - cx) / s)},${r4(-(y - cy) / s)}]`).join(", ") +
      "]",
  )
  .join(",\n");

const ts = `/**
 * The Zarnex orbit mark, as geometry. GENERATED by scripts/build-mark.mjs
 * from public/logos/zarnex-mark.svg — edit the artwork, not this file.
 *
 * Lives on its own because three things need it and none should be guessing:
 * the particle sampler, the layout guard that keeps the mark clear of the
 * headline, and the tests. A hardcoded "the mark is about 1.2 wide" is what
 * made that guard reject a perfectly good position once already.
 *
 * ${contours.length} contours, ${pts.length} points. The mark is strokes, not a solid
 * letterform, so most of these are interior holes — including the star, which
 * is carved OUT of the stroke. Fill is therefore even-odd: a point is inside
 * when it falls inside an odd number of contours. Use insideMark(), never
 * insidePolygon() on a single contour.
 *
 * See docs/07-brand-direction-one.md.
 */

export const MARK_CONTOURS: [number, number][][] = [
${body},
];

/** Even-odd across every contour, so the holes punch through. */
export function insideMark(px: number, py: number) {
  let inside = false;
  for (const poly of MARK_CONTOURS) {
    if (insidePolygon(px, py, poly)) inside = !inside;
  }
  return inside;
}

/**
 * The mark's true extent in model units — derived, never assumed.
 */
export const MARK_BOUNDS = MARK_CONTOURS.flat().reduce(
  (b, [x, y]) => ({
    minX: Math.min(b.minX, x),
    maxX: Math.max(b.maxX, x),
    minY: Math.min(b.minY, y),
    maxY: Math.max(b.maxY, y),
  }),
  { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity },
);

export function insidePolygon(px: number, py: number, poly: [number, number][]) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i];
    const [xj, yj] = poly[j];
    if (yi > py !== yj > py && px < ((xj - xi) * (py - yi)) / (yj - yi) + xi) {
      inside = !inside;
    }
  }
  return inside;
}
`;

// Favicon: the same path, bronze, with a little breathing room.
const P = 8;
const vb = `${minx - P} ${miny - P} ${maxx - minx + P * 2} ${maxy - miny + P * 2}`;
const icon = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb}"><path fill="${BRONZE}" fill-rule="evenodd" d="${d}"/></svg>`;

const check = process.argv.includes("--check");
let stale = [];
for (const [path, want] of [[TS, ts], [ICON, icon]]) {
  let have = null;
  try {
    have = readFileSync(path, "utf8");
  } catch {}
  if (have === want) continue;
  if (check) stale.push(path);
  else writeFileSync(path, want, "utf8");
}

if (check) {
  if (stale.length) {
    console.error(
      `\ncheck:mark — out of date with ${SVG}:\n` +
        stale.map((p) => "  " + p).join("\n") +
        `\n\n  run: node scripts/build-mark.mjs\n`,
    );
    process.exit(1);
  }
  console.log(`check:mark — ${contours.length} contours in step with the artwork`);
} else {
  console.log(`build:mark — ${TS} + ${ICON} from ${SVG} (${contours.length} contours, ${pts.length} pts)`);
}
